+  let match: RegExpExecArray | null;
+
+  let currentFg: string | undefined;
+  let isBold = false;
+  let isDim = false;
+
+  while ((match = ANSI_PATTERN.exec(text)) !== null) {
+    const textPart = text.slice(lastIndex, match.index);
