+        currentFg = undefined;
+        isBold = false;
+        isDim = false;
+      } else if (p === '1') {
+        isBold = true;
+      } else if (p === '2') {
+        isDim = true;
+      } else if (p === '22') {
+        isBold = false;
+        isDim = false;
+      } else if (p === '34') {
+        currentFg = 'blue';
+      } else if (p === '32') {
+        currentFg = 'green';
+      } else if (p === '31') {
+        currentFg = 'red';
+      } else if (p === '36') {
+        currentFg = 'cyan';
+      } else if (p === '37') {
