+      }
+    }
+
+    lastIndex = ANSI_PATTERN.lastIndex;
+  }
+
+  const trailing = text.slice(lastIndex);
+  if (trailing) {
+    chunks.push(createChunk(trailing, getStyle(currentFg, isBold, isDim)));
+  }
+
+  return new StyledText(chunks);
